async function handleSessionExpired(router, baseURL) {
	const usersStore = useUsersStore();
	const sessionExpiryStore = useSessionExpiryStore();
	const rootStore = useRootStore();
	if (sessionExpiryStore.handled || !usersStore.currentUser || baseURL !== rootStore.restApiContext.baseUrl && baseURL !== rootStore.publicApiContext.baseUrl) return;
	sessionExpiryStore.markHandled();
	const uiStore = useUIStore();
	uiStore.closeAllModals();
	useNotificationsStore().setNotificationsSuppressed(true);
	const currentRoute = router.currentRoute.value;
	const redirectPath = getSanitizedCurrentPath(uiStore.stateIsDirty ? router.resolve({
		name: currentRoute.name,
		params: {
			...currentRoute.params,
			nodeId: void 0
		},
		query: currentRoute.query
	}) : currentRoute);
	try {
		await usersStore.logout();
	} catch {}
	window.preventNodeViewBeforeUnload = true;
	window.location.href = router.resolve({
		name: VIEWS.SIGNIN,
		query: {
			redirect: encodeURIComponent(redirectPath),
			sessionExpired: "true"
		}
	}).href;
}
